#:package Microsoft.Data.Sqlite@9.0.0
using Microsoft.Data.Sqlite;
using var db = new SqliteConnection("Data Source=:memory:");
db.Open();
void Run(string s) { using var c = new SqliteCommand(s, db); c.ExecuteNonQuery(); }
string Plan(string q) { using var c = new SqliteCommand("EXPLAIN QUERY PLAN " + q, db); using var r = c.ExecuteReader(); r.Read(); return r.GetString(3); }
Run("CREATE TABLE Leads (Id INTEGER PRIMARY KEY, Email TEXT, CreatedAt TEXT)");
Run("CREATE INDEX ix_email ON Leads(Email)");
Run("CREATE INDEX ix_created ON Leads(CreatedAt)");
string Kind(string where) => Plan("SELECT * FROM Leads WHERE " + where).Split(' ')[0];
Console.WriteLine("A: " + Kind("Email = 'a@b.com'"));
Console.WriteLine("B: " + Kind("lower(Email) = 'a@b.com'"));
Console.WriteLine("C: " + Kind("CreatedAt >= '2026-01-01' AND CreatedAt < '2027-01-01'"));
Console.WriteLine("D: " + Kind("strftime('%Y', CreatedAt) = '2026'"));

